mapper.insert:
insert into pet (
    user_id, name, species, breed, gender, birthday, weight_kg,
    sterilized, avatar, personality_tags, personality_note,
    allergies, chronic_disease, feeding_instruction
) values (
    #{userId}, #{name}, #{species}, #{breed}, #{gender}, #{birthday}, #{weightKg},
    #{sterilized}, #{avatar}, #{personalityTags}, #{personalityNote},
    #{allergies}, #{chronicDisease}, #{feedingInstruction}
)
